export const SiteRegionKeyToLabel = {
  'NorthAmerica': 'North America',
  'LatinAmerica': 'Latin America',
  'APAC': 'APAC',
  'Europe': 'Europe'
} as const;
export type SiteRegionKey = keyof typeof SiteRegionKeyToLabel;

export interface Site {
  /**
   * @displayName Site ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  name1: string;
  /**
   * @displayName Code
   * @validationRule Required for create/update operations
   */
  code: string;
  /**
   * @displayName Occupancy Percent
   */
  occupancyPercent?: number;
  /**
   * @displayName Region
   * @validationRule Required for create/update operations
   */
  regionKey: SiteRegionKey;
  /**
   * @displayName Sort Order
   * @validationRule Required for create/update operations
   */
  sortOrder: number;
}

export const _Site = 'Site' as const;